            return FfiConverterSequenceTypeFfiUndelivered.lift(
    callWithPointer {
    uniffiRustCallWithError(FfiException) { _status ->
    UniffiLib.INSTANCE.uniffi_sdk_fn_method_notegramcore_undelivered_messages(
        it, FfiConverterUInt.lower(`limit`),_status)
}
    }
    )
    }
    

    
    /**
     * Verify a peer's `PrekeyBundleProof` (the `proof` field of a
     * `KeysPeerBundle` device entry) against pinned key-transparency trust
     * anchors, and check the signed-prekey signature against the trusted
     * `DeviceSigningKey` extracted from the proof. See `kt::device` for the
     * verifier (byte-parity ported from the server's reference
     * implementation) and `e2ee::x3dh::verify_signed_prekey` for the final
     * signature check.
     */
    @Throws(FfiException::class)override fun `verifyPeerBundle`(`proof`: kotlin.ByteArray, `trust`: FfiKeyTransparencyTrust): FfiVerifiedPrekeyBundle {
            return FfiConverterTypeFfiVerifiedPrekeyBundle.lift(
    callWithPointer {
    uniffiRustCallWithError(FfiException) { _status ->
    UniffiLib.INSTANCE.uniffi_sdk_fn_method_notegramcore_verify_peer_bundle(
        it, FfiConverterByteArray.lower(`proof`),FfiConverterTypeFfiKeyTransparencyTrust.lower(`trust`),_status)
}
    }
    )
    }
    

    

    
    companion object {
        
    @Throws(FfiException::class) fun `open`(`masterKey`: kotlin.ByteArray, `dbPath`: kotlin.String): NotegramCore {
            return FfiConverterTypeNotegramCore.lift(
    uniffiRustCallWithError(FfiException) { _status ->
    UniffiLib.INSTANCE.uniffi_sdk_fn_constructor_notegramcore_open(
        FfiConverterByteArray.lower(`masterKey`),FfiConverterString.lower(`dbPath`),_status)
}
    )
    }
    

        
    }
    
}

/**
 * @suppress
 */
public object FfiConverterTypeNotegramCore: FfiConverter<NotegramCore, Pointer> {

    override fun lower(value: NotegramCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): NotegramCore {
        return NotegramCore(value)
    }

    override fun read(buf: ByteBuffer): NotegramCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: NotegramCore) = 8UL

    override fun write(value: NotegramCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



