sealed class FfiException: kotlin.Exception() {
    
    class Store(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class Session(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class NoSession(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class BadPrekeySignature(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class BadKeyMaterial(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class NoIdentity(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * The sender named by the server is not the sender the message itself
     * authenticates. The message must not be shown.
     */
    class MisattributedMessage(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class BadInput(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class UntrustedPeerBundleProof(
        
        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.Store()
            2 -> FfiException.Session()
            3 -> FfiException.NoSession()
            4 -> FfiException.BadPrekeySignature()
            5 -> FfiException.BadKeyMaterial()
            6 -> FfiException.NoIdentity()
            7 -> FfiException.MisattributedMessage()
            8 -> FfiException.BadInput()
            9 -> FfiException.UntrustedPeerBundleProof(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.Store -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Session -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.NoSession -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.BadPrekeySignature -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.BadKeyMaterial -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.NoIdentity -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.MisattributedMessage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.BadInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.UntrustedPeerBundleProof -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Store -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.Session -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.NoSession -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.BadPrekeySignature -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.BadKeyMaterial -> {
                buf.putInt(5)
                Unit
            }
            is FfiException.NoIdentity -> {
                buf.putInt(6)
                Unit
            }
            is FfiException.MisattributedMessage -> {
                buf.putInt(7)
                Unit
            }
            is FfiException.BadInput -> {
                buf.putInt(8)
                Unit
            }
            is FfiException.UntrustedPeerBundleProof -> {
                buf.putInt(9)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * What a decrypted message contains. Read receipts ride inside the ciphertext
 * like any other message, so the server never learns that a chat was read.
 */
sealed class FfiMessageBody {
    
    data class Text(
        val `text`: kotlin.String) : FfiMessageBody() {
        companion object
    }
    
    /**
     * Everything up to this timestamp has been read by the peer.
     */
    data class ReadReceipt(
        val `upToCreatedAt`: kotlin.Long) : FfiMessageBody() {
        companion object
    }
    
    /**
     * Relayed from another chat, naming who wrote it first. The attribution
     * is the forwarder's claim, not a proof — show it, do not trust it.
     */
    data class Forwarded(
        val `text`: kotlin.String, 
        val `originUsername`: kotlin.String, 
        val `originCreatedAt`: kotlin.Long) : FfiMessageBody() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiMessageBody : FfiConverterRustBuffer<FfiMessageBody>{
    override fun read(buf: ByteBuffer): FfiMessageBody {
        return when(buf.getInt()) {
            1 -> FfiMessageBody.Text(
                FfiConverterString.read(buf),
                )
            2 -> FfiMessageBody.ReadReceipt(
                FfiConverterLong.read(buf),
                )
            3 -> FfiMessageBody.Forwarded(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterLong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiMessageBody) = when(value) {
        is FfiMessageBody.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
        is FfiMessageBody.ReadReceipt -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterLong.allocationSize(value.`upToCreatedAt`)
            )
        }
        is FfiMessageBody.Forwarded -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
                + FfiConverterString.allocationSize(value.`originUsername`)
                + FfiConverterLong.allocationSize(value.`originCreatedAt`)
            )
        }
    }

    override fun write(value: FfiMessageBody, buf: ByteBuffer) {
        when(value) {
            is FfiMessageBody.Text -> {
                buf.putInt(1)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
            is FfiMessageBody.ReadReceipt -> {
                buf.putInt(2)
                FfiConverterLong.write(value.`upToCreatedAt`, buf)
                Unit
            }
            is FfiMessageBody.Forwarded -> {
                buf.putInt(3)
                FfiConverterString.write(value.`text`, buf)
                FfiConverterString.write(value.`originUsername`, buf)
                FfiConverterLong.write(value.`originCreatedAt`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * How far an outgoing message got. Only ever moves forward.
 */

enum class FfiMessageStatus {
    
    SENT,
    DELIVERED,
    READ;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeFfiMessageStatus: FfiConverterRustBuffer<FfiMessageStatus> {
    override fun read(buf: ByteBuffer) = try {
        FfiMessageStatus.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: FfiMessageStatus) = 4UL

    override fun write(value: FfiMessageStatus, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







